import {clamp,formatTime,parseSubtitles,makeCandidates,chooseClips,validRange} from './logic.js';
const $=id=>document.getElementById(id),v=$('video');
const state={url:null,fileName:'',duration:0,cues:[],samples:[],candidates:[],clips:[],style:'dynamic',target:30,mode:'source',busy:false,scanId:0,loadingId:0,editId:null,previewIndex:0,transition:false,demo:false,exportJob:null,downloadUrl:null};
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4200);}
function total(){return state.clips.reduce((s,c)=>s+c.end-c.start,0);}
function setBusy(busy){state.busy=busy;document.body.classList.toggle('busy',busy);for(const id of ['videoFile','subtitleFile','analyzeBtn','demoBtn','aspect','exportBtn','addClipBtn','selectAllBtn','saveProjectBtn','targetDuration'])$(id).disabled=busy||(['analyzeBtn','addClipBtn'].includes(id)&&!state.url)||(['exportBtn','saveProjectBtn'].includes(id)&&!state.clips.length);}
function waitEvent(el,event,timeout=15000,signal){return new Promise((resolve,reject)=>{if(signal?.aborted)return reject(new Error('已取消'));let t;const cleanup=()=>{clearTimeout(t);el.removeEventListener(event,ok);el.removeEventListener('error',fail);signal?.removeEventListener('abort',abort);};const ok=()=>{cleanup();resolve();};const fail=()=>{cleanup();reject(new Error('视频无法解码，请尝试 H.264 编码的 MP4 文件'));};const abort=()=>{cleanup();reject(new Error('已取消'));};el.addEventListener(event,ok,{once:true});el.addEventListener('error',fail,{once:true});signal?.addEventListener('abort',abort,{once:true});t=setTimeout(()=>{cleanup();reject(new Error('读取视频超时，请重试或换一段较短的视频'));},timeout);});}
async function seek(video,time,signal){time=clamp(time,0,Math.max(0,video.duration-.015));if(Math.abs(video.currentTime-time)<.015&&video.readyState>=2)return;const done=waitEvent(video,'seeked',15000,signal);video.currentTime=time;await done;if(video.readyState<2)await waitEvent(video,'loadeddata',15000,signal);}
async function makeVideo(url,signal){const video=document.createElement('video');video.preload='auto';video.playsInline=true;video.crossOrigin='anonymous';const loaded=waitEvent(video,'loadeddata',20000,signal);video.src=url;video.load();await loaded;return video;}
function disposeVideo(video){if(!video)return;video.pause();video.removeAttribute('src');video.load();video.remove();}
function resetPreview(){v.pause();state.mode='source';state.transition=false;state.previewIndex=0;state.singleEnd=null;updateMode();}
function updateMode(){$('sourceTab').classList.toggle('active',state.mode==='source');$('montageTab').classList.toggle('active',state.mode==='montage');$('previewBadge').textContent=state.mode==='source'?'SOURCE':'HIGHLIGHT';const [a,b]=$('aspect').value.split(':').map(Number);$('viewer').style.aspectRatio=state.mode==='montage'?`${a}/${b}`:'16/9';$('viewer').style.maxHeight=state.mode==='montage'?'520px':'';$('viewer').style.maxWidth=state.mode==='montage'?(a<b?'293px':a===b?'520px':''):'';$('viewer').style.marginInline='auto';updatePlayer();}
async function loadMedia(blob,name,isDemo=false){if(state.busy)return;const id=++state.loadingId,newUrl=URL.createObjectURL(blob);setBusy(true);resetPreview();try{const probe=await makeVideo(newUrl);if(!Number.isFinite(probe.duration)||probe.duration<=.1||!probe.videoWidth){disposeVideo(probe);throw new Error('无法识别有效的视频时长');}const duration=probe.duration;disposeVideo(probe);if(id!==state.loadingId)return;const old=state.url;state.url=newUrl;state.fileName=name;state.duration=duration;state.demo=isDemo;state.samples=[];state.candidates=[];state.clips=[];state.cues=[];$('subtitleLabel').textContent='导入 SRT / VTT 字幕';const ready=waitEvent(v,'loadeddata');v.src=newUrl;v.load();await ready;if(old)URL.revokeObjectURL(old);$('viewerEmpty').hidden=true;$('fileLabel').textContent=name;$('fileDetail').textContent=`${formatTime(duration)} · ${(blob.size/1024/1024).toFixed(1)} MB`;$('projectTitle').textContent=isDemo?'Big Buck Bunny · 示例混剪':name.replace(/\.[^.]+$/,'');$('resolutionLabel').textContent=`${v.videoWidth} × ${v.videoHeight}`;$('footerStatus').textContent=isDemo?'示例：© Blender Foundation · CC BY 3.0':'本地素材 · 不上传服务器';$('playBtn').disabled=false;$('seekBar').disabled=false;$('durationTime').textContent=formatTime(duration);$('candidateSubtitle').textContent='准备发现精彩片刻';render();await seek(v,Math.min(4,duration*.1));toast(isDemo?'示例影片已就绪，正在寻找高光':'影片已导入，可以开始寻找高光');}catch(e){if(state.url!==newUrl)URL.revokeObjectURL(newUrl);toast(e.message);}finally{setBusy(false);}if(isDemo&&state.url===newUrl)await analyze();}
async function loadDemo(){if(state.busy)return;setBusy(true);$('demoBtn').textContent='正在读取示例…';try{const r=await fetch('assets/big-buck-bunny-30s.mp4');if(!r.ok)throw new Error('示例加载失败，请导入本地视频');const blob=await r.blob();setBusy(false);await loadMedia(blob,'Big Buck Bunny · 30 秒片段.mp4',true);}catch(e){toast(e.message);setBusy(false);}finally{$('demoBtn').textContent='重新加载示例影片';}}
$('videoFile').onchange=e=>{const file=e.target.files[0];if(file)loadMedia(file,file.name);e.target.value='';};
$('demoBtn').onclick=loadDemo;
for(const type of ['dragover','dragleave','drop'])$('dropzone').addEventListener(type,e=>{e.preventDefault();$('dropzone').classList.toggle('dragover',type==='dragover');if(type==='drop'&&!state.busy){const file=e.dataTransfer.files[0];if(file)loadMedia(file,file.name);}});
$('subtitleFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('字幕过大，请使用小于 5 MB 的 SRT / VTT 文件');const cues=parseSubtitles(await file.text(),state.duration||Infinity);if(!cues.length)throw new Error('没有识别到有效字幕，请检查时间码格式');state.cues=cues;$('subtitleLabel').textContent=`${file.name} · ${cues.length} 条`;toast('字幕已导入，再次寻找高光即可结合对白筛选');updatePlayer();}catch(err){toast(err.message);}e.target.value='';};
document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{if(state.busy)return;state.style=b.dataset.style;document.querySelectorAll('[data-style]').forEach(x=>x.classList.toggle('selected',x===b));if(state.samples.length)rebuildCandidates();});
$('targetDuration').oninput=e=>{state.target=Number(e.target.value);$('targetLabel').textContent=`${state.target} 秒`;};
$('targetDuration').onchange=()=>{if(state.candidates.length&&!state.busy){resetPreview();state.clips=chooseClips(state.candidates,state.target);render();toast('已按目标时长重新选择片段');}};
$('aspect').onchange=()=>{updateMode();toast('画面将等比缩放并保留黑边，不裁掉主体');};
async function analyze(){if(!state.url||state.busy)return;const token=++state.scanId,abort=new AbortController();state.scanAbort=abort;setBusy(true);resetPreview();$('scanStatus').hidden=false;$('scanProgress').value=0;$('analyzeBtn').textContent='正在分析画面…';let probe;try{probe=await makeVideo(state.url,abort.signal);probe.muted=true;const canvas=document.createElement('canvas');canvas.width=160;canvas.height=90;const ctx=canvas.getContext('2d',{willReadFrequently:true});const count=Math.min(180,Math.max(12,Math.ceil(state.duration/1.4)));const samples=[];let prev=null;for(let i=0;i<count;i++){if(token!==state.scanId)throw new Error('已取消');const t=clamp((i+.5)*state.duration/count,0,state.duration-.05);await seek(probe,Math.max(0,t-.18),abort.signal);ctx.drawImage(probe,0,0,160,90);const before=ctx.getImageData(0,0,160,90).data;await seek(probe,t,abort.signal);ctx.drawImage(probe,0,0,160,90);const pixels=ctx.getImageData(0,0,160,90).data;let delta=0,change=0,brightness=0;for(let p=0;p<pixels.length;p+=16){delta+=Math.abs(pixels[p]-before[p])+Math.abs(pixels[p+1]-before[p+1])+Math.abs(pixels[p+2]-before[p+2]);if(prev)change+=Math.abs(pixels[p]-prev[p])+Math.abs(pixels[p+1]-prev[p+1])+Math.abs(pixels[p+2]-prev[p+2]);brightness+=(pixels[p]+pixels[p+1]+pixels[p+2])/3;}const n=pixels.length/16;delta=delta/n/3*.75+(prev?change/n/3:0)*.25;if(brightness/n<9)delta*=.2;samples.push({time:t,delta,thumb:canvas.toDataURL('image/jpeg',.72)});prev=pixels;$('scanProgress').value=(i+1)/count*100;$('analysisNote').textContent=`正在抽取画面 ${i+1} / ${count} · ${formatTime(t)}`;await new Promise(r=>setTimeout(r,0));}if(token!==state.scanId)return;state.samples=samples;rebuildCandidates();$('analysisNote').textContent=`已抽取 ${samples.length} 组画面。优先度来自画面变化${state.cues.length?'与对白线索':''}，不代表剧情质量。`;toast(`找到 ${state.candidates.length} 个候选，已组成 ${total().toFixed(1)} 秒混剪`);}catch(e){toast(e.message==='已取消'?'已停止分析，原有剪辑保留':e.message);$('analysisNote').textContent='可再次分析，或在播放位置手动标记片段。';}finally{disposeVideo(probe);$('scanStatus').hidden=true;$('analyzeBtn').innerHTML='<span>✧</span> 寻找高光';state.scanAbort=null;setBusy(false);}}
function rebuildCandidates(){resetPreview();state.candidates=makeCandidates(state.samples,state.cues,state.duration,state.style);state.clips=chooseClips(state.candidates,state.target);render();}
$('analyzeBtn').onclick=analyze;
$('cancelScan').onclick=()=>{state.scanId++;state.scanAbort?.abort();};
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function render(){const chosen=new Set(state.clips.map(c=>c.id));const candidates=[...state.candidates].sort($('sortSelect').value==='time'?(a,b)=>a.start-b.start:(a,b)=>b.score-a.score);$('candidateCount').textContent=candidates.length;$('candidateSubtitle').textContent=candidates.length?'本地分析 · 可人工复核':state.url?'可以分析或手动标记':'等待导入素材';$('candidates').innerHTML=candidates.length?candidates.map(c=>`<article class="candidate ${chosen.has(c.id)?'chosen':''}" data-id="${c.id}"><div class="candidate-top"><button class="candidate-thumb" data-preview="${c.id}" aria-label="预览 ${escapeHtml(c.title)}"><img src="${c.thumb}" alt="候选片段画面"><span>${(c.end-c.start).toFixed(1)}s</span></button><div class="candidate-title"><strong title="${escapeHtml(c.title)}">${escapeHtml(c.title)}</strong><span class="score">${c.score===null?'手动标记':`优先度 ${c.score}`}<small>${c.score===null?'':c.text?'对白 + 画面':'画面变化'}</small></span></div></div><div class="candidate-meta"><span>${formatTime(c.start)} — ${formatTime(c.end)}</span><button data-edit="${c.id}" aria-label="调整 ${escapeHtml(c.title)}">微调</button><label><input type="checkbox" data-toggle="${c.id}" ${chosen.has(c.id)?'checked':''}>选入</label></div></article>`).join(''):'<div class="candidate-empty"><span>✧</span><h3>精彩片刻，等你发现</h3><p>点击「寻找高光」自动筛选<br>或在喜欢的位置手动标记</p></div>';
  $('timeline').classList.toggle('empty',!state.clips.length);$('timeline').innerHTML=state.clips.length?state.clips.map((c,i)=>`<button class="timeline-clip" data-edit="${c.id}" style="flex-grow:${c.end-c.start}" aria-label="编辑第 ${i+1} 段 ${escapeHtml(c.title)}"><img src="${c.thumb}" alt=""><b>${String(i+1).padStart(2,'0')}</b><span>${(c.end-c.start).toFixed(1)}s · ${escapeHtml(c.title)}</span></button>`).join(''):'<span>挑选右侧高光，组成你的故事</span>';$('timelineCount').textContent=`${state.clips.length} 个片段`;$('montageDuration').textContent=formatTime(total(),true);$('summaryDuration').textContent=`${total().toFixed(1)} 秒`;$('selectionCount').textContent=`已选 ${state.clips.length} 段`;$('exportBtn').disabled=!state.clips.length||state.busy;$('saveProjectBtn').disabled=!state.clips.length||state.busy;$('selectAllBtn').disabled=!candidates.length||state.busy;$('selectAllBtn').textContent=state.clips.length===candidates.length&&candidates.length?'取消全选':'全部选择';document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewCandidate(b.dataset.preview));document.querySelectorAll('[data-toggle]').forEach(b=>b.onchange=()=>toggleClip(b.dataset.toggle));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editClip(b.dataset.edit));updatePlayer();}
function toggleClip(id){if(state.busy)return;resetPreview();if(state.clips.some(c=>c.id===id))state.clips=state.clips.filter(c=>c.id!==id);else{const c=state.candidates.find(c=>c.id===id);state.clips.push({...c});}render();}
$('selectAllBtn').onclick=()=>{if(state.busy)return;resetPreview();state.clips=state.clips.length===state.candidates.length?[]:[...state.candidates].sort((a,b)=>a.start-b.start).map(c=>({...c}));render();};
$('sortSelect').onchange=render;
async function previewCandidate(id){if(state.busy)return;const c=state.candidates.find(x=>x.id===id);resetPreview();await seek(v,c.start);state.singleEnd=c.end;v.play().catch(()=>toast('请点击播放按钮开始预览'));}
function editClip(id){if(state.busy)return;const c=state.clips.find(c=>c.id===id)||state.candidates.find(c=>c.id===id);if(!c)return;v.pause();state.editId=id;$('clipTitle').value=c.title;$('clipStart').value=c.start.toFixed(3);$('clipEnd').value=c.end.toFixed(3);$('clipStart').max=state.duration;$('clipEnd').max=state.duration;$('clipError').textContent=`原片长度 ${state.duration.toFixed(2)} 秒`;const i=state.clips.findIndex(c=>c.id===id);$('moveEarlierBtn').disabled=i<=0;$('moveLaterBtn').disabled=i<0||i===state.clips.length-1;$('removeClipBtn').disabled=i<0;$('clipDialog').showModal();}
$('saveClipBtn').onclick=async()=>{const start=Number($('clipStart').value),end=Number($('clipEnd').value);if(!$('clipStart').value||!$('clipEnd').value||!validRange(start,end,state.duration)){$('clipError').textContent='入点必须不小于 0，出点不得超过原片，片段至少 0.1 秒。';return;}const title=$('clipTitle').value.trim()||'未命名片段';$('saveClipBtn').disabled=true;try{await seek(v,start);const canvas=document.createElement('canvas');canvas.width=200;canvas.height=112;canvas.getContext('2d').drawImage(v,0,0,200,112);const thumb=canvas.toDataURL('image/jpeg',.72);for(const arr of [state.clips,state.candidates]){const c=arr.find(c=>c.id===state.editId);if(c)Object.assign(c,{start,end,title,thumb,score:null,reason:'人工微调'});}resetPreview();render();$('clipDialog').close();toast('片段已更新');}catch(e){$('clipError').textContent=e.message;}finally{$('saveClipBtn').disabled=false;}};
function moveClip(direction){const i=state.clips.findIndex(c=>c.id===state.editId),j=i+direction;if(i<0||j<0||j>=state.clips.length)return;[state.clips[i],state.clips[j]]=[state.clips[j],state.clips[i]];resetPreview();render();$('moveEarlierBtn').disabled=j===0;$('moveLaterBtn').disabled=j===state.clips.length-1;toast('已更新片段顺序');}
$('moveEarlierBtn').onclick=()=>moveClip(-1);$('moveLaterBtn').onclick=()=>moveClip(1);$('removeClipBtn').onclick=()=>{state.clips=state.clips.filter(c=>c.id!==state.editId);resetPreview();render();$('clipDialog').close();};
$('addClipBtn').onclick=()=>{if(state.busy||!state.url)return;resetPreview();const canvas=document.createElement('canvas');canvas.width=200;canvas.height=112;canvas.getContext('2d').drawImage(v,0,0,200,112);const start=clamp(v.currentTime,0,Math.max(0,state.duration-.5)),end=Math.min(state.duration,start+4);const c={id:`manual-${Date.now()}`,start,end,title:`手选片段 ${state.candidates.filter(c=>c.score===null).length+1}`,thumb:canvas.toDataURL('image/jpeg',.7),score:null,reason:'人工标记',text:''};state.candidates.push(c);state.clips.push({...c});render();editClip(c.id);};
function updatePlayer(){const montage=state.mode==='montage';const elapsed=montage?state.clips.slice(0,state.previewIndex).reduce((n,c)=>n+c.end-c.start,0)+Math.max(0,v.currentTime-(state.clips[state.previewIndex]?.start||0)):v.currentTime;const duration=montage?total():state.duration;$('currentTime').textContent=formatTime(elapsed);$('durationTime').textContent=formatTime(duration);$('seekBar').value=duration?clamp(elapsed/duration*1000,0,1000):0;$('playBtn').textContent=v.paused?'▶':'Ⅱ';const cue=state.cues.find(c=>v.currentTime>=c.start&&v.currentTime<c.end);$('subtitleOverlay').textContent=cue?.text||'';}
async function advanceMontage(){if(state.transition||state.mode!=='montage')return;state.transition=true;const wasPlaying=!v.paused||v.ended;v.pause();try{if(state.previewIndex>=state.clips.length-1){state.previewIndex=0;await seek(v,state.clips[0].start);}else{state.previewIndex++;await seek(v,state.clips[state.previewIndex].start);if(wasPlaying)await v.play();}}catch(e){toast(e.message);}finally{state.transition=false;updatePlayer();}}
function tick(){if(!state.busy&&!v.paused){if(state.mode==='montage'&&state.clips.length&&v.currentTime>=state.clips[state.previewIndex].end-.035)void advanceMontage();else if(state.singleEnd&&v.currentTime>=state.singleEnd){v.pause();state.singleEnd=null;}}updatePlayer();requestAnimationFrame(tick);}requestAnimationFrame(tick);
v.addEventListener('ended',()=>{if(state.mode==='montage')void advanceMontage();});
$('playBtn').onclick=async()=>{if(state.busy||!state.url)return;state.singleEnd=null;try{if(v.paused){if(state.mode==='montage'&&state.clips.length){const c=state.clips[state.previewIndex];if(v.currentTime<c.start||v.currentTime>=c.end)await seek(v,c.start);}await v.play();}else v.pause();}catch{toast('暂时无法播放，请重新导入影片');}};
$('sourceTab').onclick=()=>{if(!state.busy)resetPreview();};
$('montageTab').onclick=async()=>{if(state.busy)return;if(!state.clips.length){toast('先选择至少一个片段');return;}v.pause();state.mode='montage';state.previewIndex=0;state.singleEnd=null;await seek(v,state.clips[0].start);updateMode();};
$('seekBar').oninput=e=>{if(state.busy)return;state.singleEnd=null;const t=Number(e.target.value)/1000*(state.mode==='source'?state.duration:total());if(state.mode==='source')v.currentTime=t;else{let left=t;for(let i=0;i<state.clips.length;i++){const c=state.clips[i],d=c.end-c.start;if(left<=d||i===state.clips.length-1){state.previewIndex=i;v.currentTime=c.start+Math.min(left,d-.02);break;}left-=d;}}};
$('muteBtn').onclick=()=>{v.muted=!v.muted;$('muteBtn').textContent=v.muted?'♩':'♫';$('muteBtn').setAttribute('aria-label',v.muted?'取消静音':'静音');};
$('fullscreenBtn').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('viewer').requestFullscreen?.().catch(()=>toast('当前浏览器不支持全屏'));};
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('playBtn').click();}});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('saveProjectBtn').onclick=()=>{const project={app:'CineCut',version:1,source:state.fileName,sourceDuration:state.duration,aspect:$('aspect').value,style:state.style,selectionMethod:'local-frame-difference-and-subtitle-heuristics',attribution:state.demo?'Edited excerpt of Big Buck Bunny. © 2008 Blender Foundation / www.bigbuckbunny.org. CC BY 3.0 https://creativecommons.org/licenses/by/3.0/':undefined,clips:state.clips.map(({thumb,...c})=>c),subtitles:state.cues};download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),'CineCut-剪辑方案.json');toast('已保存片段时间码与顺序（不包含视频）');};
function exportMime(){if(!globalThis.MediaRecorder)return null;return ['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));}
$('exportBtn').onclick=()=>{if(!state.clips.length||state.busy)return;v.pause();$('exportDuration').textContent=formatTime(total(),true);$('exportStatus').textContent=exportMime()?'':'此浏览器暂不支持 WebM 导出，请使用新版 Chrome 或 Edge。';$('startExportBtn').disabled=!exportMime();$('startExportBtn').hidden=false;$('downloadLink').hidden=true;$('exportProgress').hidden=true;$('exportDialog').showModal();};
function drawFrame(ctx,video,canvas,time,burn){const {width:w,height:h}=canvas;ctx.fillStyle='#000';ctx.fillRect(0,0,w,h);const scale=Math.min(w/video.videoWidth,h/video.videoHeight),vw=video.videoWidth*scale,vh=video.videoHeight*scale;ctx.drawImage(video,(w-vw)/2,(h-vh)/2,vw,vh);if(burn){const cue=state.cues.find(c=>time>=c.start&&time<c.end);if(cue){const size=Math.round(Math.min(w,h)*.043);ctx.font=`600 ${size}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='bottom';const lines=[];for(const original of cue.text.split('\n')){let line='';for(const char of original){if(ctx.measureText(line+char).width>w*.86&&line){lines.push(line);line=char;}else line+=char;}if(line)lines.push(line);}lines.slice(0,4).forEach((line,i,a)=>{const y=h*.91-(a.length-1-i)*size*1.35;ctx.lineWidth=size*.16;ctx.strokeStyle='#000';ctx.strokeText(line,w/2,y);ctx.fillStyle='#fff';ctx.fillText(line,w/2,y);});}}if(state.demo){ctx.font=`${Math.max(11,w*.012)}px sans-serif`;ctx.textAlign='left';ctx.fillStyle='#fff9';ctx.fillText('Big Buck Bunny · © Blender Foundation · CC BY 3.0 · Edited excerpt',w*.02,h*.98);}}
async function startExport(){if(state.exportJob)return;const mime=exportMime();if(!mime)return;$('exportPreview').pause();$('exportPreview').hidden=true;const ac=new (window.AudioContext||window.webkitAudioContext)();await ac.resume();const job={abort:new AbortController(),recorder:null,video:null,stream:null,ac,cancelled:false};state.exportJob=job;setBusy(true);$('startExportBtn').hidden=true;$('downloadLink').hidden=true;$('closeExportBtn').disabled=true;$('cancelExportBtn').hidden=false;$('exportProgress').hidden=false;$('exportProgress').value=0;$('exportStatus').textContent='正在准备画面与音轨…';const clips=state.clips.map(c=>({...c}));const burn=$('burnSubtitles').checked;let timer,watchdog,wake;try{if(navigator.wakeLock)try{wake=await navigator.wakeLock.request('screen');}catch{}const video=await makeVideo(state.url,job.abort.signal);job.video=video;video.style.cssText='position:fixed;left:-2px;bottom:-2px;width:1px;height:1px;opacity:0;pointer-events:none';document.body.append(video);const canvas=document.createElement('canvas');const [a,b]=$('aspect').value.split(':').map(Number),base=Number($('quality').value);canvas.width=a>=b?Math.round(base*a/b/2)*2:base;canvas.height=a>=b?base:Math.round(base*b/a/2)*2;const ctx=canvas.getContext('2d',{alpha:false});const source=ac.createMediaElementSource(video),dest=ac.createMediaStreamDestination();source.connect(dest);source.connect(ac.destination);const canvasStream=canvas.captureStream(30);const stream=new MediaStream([...canvasStream.getVideoTracks(),...dest.stream.getAudioTracks()]);job.stream=stream;const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:base===1080?8000000:4000000});job.recorder=recorder;const chunks=[];const stopped=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=resolve;recorder.onerror=()=>reject(new Error('浏览器编码失败，请降低清晰度重试'));});stopped.catch(()=>{});await seek(video,clips[0].start,job.abort.signal);drawFrame(ctx,video,canvas,video.currentTime,burn);let completed=0;recorder.start(250);recorder.pause();for(let i=0;i<clips.length;i++){if(job.cancelled)throw new Error('已取消');const c=clips[i];await seek(video,c.start,job.abort.signal);drawFrame(ctx,video,canvas,video.currentTime,burn);await video.play();recorder.resume();await new Promise((resolve,reject)=>{let last=video.currentTime,lastAdvance=performance.now();const stop=()=>{clearInterval(timer);clearInterval(watchdog);video.removeEventListener('error',fail);job.abort.signal.removeEventListener('abort',cancel);};const fail=()=>{stop();reject(new Error('导出中视频解码失败'));};const cancel=()=>{stop();reject(new Error('已取消'));};job.abort.signal.addEventListener('abort',cancel,{once:true});video.addEventListener('error',fail,{once:true});const frame=()=>{drawFrame(ctx,video,canvas,video.currentTime,burn);const elapsed=completed+clamp(video.currentTime-c.start,0,c.end-c.start);$('exportProgress').value=elapsed/total()*100;$('exportStatus').textContent=`正在导出第 ${i+1} / ${clips.length} 段 · ${Math.round(elapsed/total()*100)}%`;if(video.currentTime>=c.end-.025||video.ended){video.pause();recorder.pause();stop();resolve();}};timer=setInterval(frame,1000/30);watchdog=setInterval(()=>{if(video.currentTime!==last){last=video.currentTime;lastAdvance=performance.now();}else if(performance.now()-lastAdvance>15000){stop();reject(new Error('播放中断，导出已停止。请保持页面前台后重试。'));}},1000);});completed+=c.end-c.start;}if(recorder.state!=='inactive')recorder.stop();await stopped;const blob=new Blob(chunks,{type:recorder.mimeType});if(blob.size<1024)throw new Error('生成的视频为空，请重试');if(state.downloadUrl)URL.revokeObjectURL(state.downloadUrl);state.downloadUrl=URL.createObjectURL(blob);$('downloadLink').href=state.downloadUrl;$('downloadLink').download='CineCut-电影高光.webm';$('downloadLink').hidden=false;$('exportPreview').src=state.downloadUrl;$('exportPreview').hidden=false;$('exportProgress').value=100;$('exportStatus').textContent=`成片已生成 · ${(blob.size/1024/1024).toFixed(1)} MB · WebM`;$('startExportBtn').textContent='重新导出';toast('高光成片已就绪，可以下载了');}catch(e){$('exportStatus').textContent=job.cancelled?'导出已取消，可以重新开始。':e.message;$('startExportBtn').textContent='重新导出';}finally{clearInterval(timer);clearInterval(watchdog);if(job.recorder&&job.recorder.state!=='inactive')job.recorder.stop();job.stream?.getTracks().forEach(t=>t.stop());disposeVideo(job.video);await ac.close();if(wake)await wake.release();state.exportJob=null;$('closeExportBtn').disabled=false;$('cancelExportBtn').hidden=true;$('startExportBtn').hidden=false;setBusy(false);}}
$('startExportBtn').onclick=()=>startExport().catch(e=>{toast(e.message);$('exportStatus').textContent=e.message;});
$('cancelExportBtn').onclick=()=>{if(state.exportJob){state.exportJob.cancelled=true;state.exportJob.abort.abort();}};
$('exportDialog').addEventListener('close',()=>$('exportPreview').pause());
$('exportDialog').addEventListener('cancel',e=>{if(state.exportJob)e.preventDefault();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.exportJob){state.exportJob.cancelled=true;state.exportJob.abort.abort();}});
$('methodContent').innerHTML=`<h3>先找到证据，再做判断</h3><p>参考 GeekCatX 的 <a href="https://x.com/GeekCatX/status/2100951857049006110" target="_blank" rel="noopener">Jev 实操文章</a>及其<a href="https://x.com/GeekCatX/status/2101223068580643172" target="_blank" rel="noopener">后续混剪案例</a>：把抽帧、判断和剪辑执行分开，让每一次选择可以复核。</p><ol><li><strong>发现候选。</strong> 对影片稀疏抽帧，比较前后画面变化；导入字幕后结合对白关键词。长片最多采样 180 组，细节可能遗漏，可以随时人工标记。</li><li><strong>按标准排序。</strong> 快节奏模式优先画面变化；剧情模式提高对白线索权重。优先度是当前素材内的启发式排序，不是剧情质量分，也不是模型置信度。</li><li><strong>由你完成选择。</strong> 预览、修改入点出点、调整次序，再导出真实视频。原片时长与成片时长由代码计算。</li></ol><h3>当前版本的能力</h3><p>本机分析、本机剪辑，不上传你的电影。<a href="https://docs.typesafe.ai/models" target="_blank" rel="noopener">Jev 官方</a>目前只接收文本；这个版本未接入 Jev 或视觉模型，不会自动理解人物、剧情或音乐节拍。画面保留原比例，竖屏输出添加黑边。导出保留选中片段的原声，不自动添加配乐。</p><h3>示例素材</h3><p>Big Buck Bunny，© 2008 Blender Foundation / <a href="https://www.bigbuckbunny.org" target="_blank" rel="noopener">www.bigbuckbunny.org</a>，<a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a>。此处使用 30 秒片段；导出的示例为重新剪辑版本。</p>`;
$('methodBtn').onclick=()=>$('methodDialog').showModal();
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_highlight_project',description:'Read the current local movie project and selected highlight segments.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters accepted');return {source:state.fileName,duration:state.duration,candidateIds:state.candidates.map(c=>c.id),analysis:'local-heuristics',clips:state.clips.map(({thumb,...c})=>c),total:total()};}},{name:'set_highlight_selection',description:'Stage an ordered selection of existing candidate clip IDs. Does not export or upload video.',inputSchema:{type:'object',properties:{clipIds:{type:'array',items:{type:'string'},uniqueItems:true}},required:['clipIds'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(state.busy)throw new Error('Processing in progress');if(!input||Object.keys(input).some(k=>k!=='clipIds')||!Array.isArray(input.clipIds)||new Set(input.clipIds).size!==input.clipIds.length||input.clipIds.some(id=>typeof id!=='string'||!state.candidates.some(c=>c.id===id)))throw new Error('Provide unique existing candidate IDs');resetPreview();state.clips=input.clipIds.map(id=>({...state.candidates.find(c=>c.id===id)}));render();return {selected:state.clips.map(c=>c.id),duration:total()};}}];for(const tool of tools)Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
